import sys

def solve():
    # Read input from stdin
    try:
        input_data = sys.stdin.read().split()
        if not input_data:
            return
        n = int(input_data[0])
        m = int(input_data[1])
        s = input_data[2]
    except (ValueError, IndexError):
        return

    # We need to find the minimum X (number of logo T-shirts to buy)
    # Total available T-shirts: M plain, X logo.
    # Total T-shirts = M + X.
    # On any day before a wash (0), the number of logo T-shirts used
    # must be <= X, and the total T-shirts used must be <= M + X.

    # Actually, we can binary search or just iterate on X.
    # Given the constraints (N <= 1000), we can simulate for each X.

    for x in range(n + 1):
        plain_available = m
        logo_available = x
        possible = True

        for char in s:
            if char == '0':
                # Wash day: reset availability
                plain_available = m
                logo_available = x
            elif char == '1':
                # Meal: try using plain, then logo
                if plain_available > 0:
                    plain_available -= 1
                elif logo_available > 0:
                    logo_available -= 1
                else:
                    possible = False
                    break
            elif char == '2':
                # Contest: must use logo
                if logo_available > 0:
                    logo_available -= 1
                else:
                    possible = False
                    break

        if possible:
            print(x)
            return

