def solution(s):
    s = list(s)

    # Handle hours - first digit (index 0)
    if s[0] == '?':
        # If second hour digit is ? or <= 1, we can use 1 for first digit
        # Otherwise, we must use 0
        if s[1] == '?' or s[1] <= '1':
            s[0] = '1'
        else:
            s[0] = '0'

    # Handle hours - second digit (index 1)
    if s[1] == '?':
        # If first digit is '1', second digit can be at most '1' (for 11)
        # If first digit is '0', second digit can be at most '9' (for 09)
        if s[0] == '1':
            s[1] = '1'
        else:
            s[1] = '9'

    # Handle minutes - first digit (index 3)
    if s[3] == '?':
        # First minute digit can always be 5 for maximum value
        s[3] = '5'

    # Handle minutes - second digit (index 4)
    if s[4] == '?':
        # Second minute digit can always be 9 for maximum value
        s[4] = '9'

    return ''.join(s)
