from collections import deque
import sys

def solve():
    input = sys.stdin.readline
    H, W = map(int, input().strip().split())
    grid = [list(input().strip()) for _ in range(H)]

    # Check if a cell is blocked (adjacent to magnet)
    blocked = [[False] * W for _ in range(H)]
    dirs = [(-1,0), (1,0), (0,-1), (0,1)]

    for i in range(H):
        for j in range(W):
            if grid[i][j] == '#':
                for di, dj in dirs:
                    ni, nj = i + di, j + dj
                    if 0 <= ni < H and 0 <= nj < W:
                        blocked[ni][nj] = True

    visited = [[-1] * W for _ in range(H)]
    max_freedom = 0

    for i in range(H):
        for j in range(W):
            if grid[i][j] == '.' and visited[i][j] == -1:
                # BFS to find connected component
                q = deque()
                q.append((i, j))
                visited[i][j] = (i, j)  # mark with component root
                cells = [(i, j)]
                while q:
                    x, y = q.popleft()
                    for dx, dy in dirs:
                        nx, ny = x + dx, y + dy
                        if 0 <= nx < H and 0 <= ny < W and grid[nx][ny] == '.' and not blocked[nx][ny] and visited[nx][ny] == -1:
                            visited[nx][ny] = (i, j)
                            q.append((nx, ny))
                            cells.append((nx, ny))

                # Count unique reachable cells including blocked-adjacent ones
                # Actually for degree of freedom, you can also stay at blocked-adjacent cells themselves,
                # so the component size is just all '.' cells connected without moving through blocked cells

                # However, blocked cells (magnet adjacent) are still visited but cannot move out.
                # So we need a second BFS that allows starting from anywhere within connected component
                # and counts reachable cells even if they are blocked (just means you stop there).

                # Simpler: just recompute from this component considering blocked cells as passable endpoints
                seen = set()
                q2 = deque(cells)
                for cx, cy in cells:
                    seen.add((cx, cy))
                while q2:
                    x, y = q2.popleft()
                    for dx, dy in dirs:
                        nx, ny = x + dx, y + dy
                        if 0 <= nx < H and 0 <= ny < W and grid[nx][ny] == '.' and (nx, ny) not in seen:
                            # If this cell is blocked, we can still count it but cannot move beyond
                            seen.add((nx, ny))
                            if not blocked[nx][ny]:
                                q2.append((nx, ny))

                size = len(seen)
                if size > max_freedom:
                    max_freedom = size

    print(max_freedom)

if __name__ == "__main__":
    solve()
