def numberOfSpecialChars(word: str) -> int:
    # Use sets to track which lowercase and uppercase letters are present
    lower_present = set()
    upper_present = set()

    for char in word:
        if char.islower():
            lower_present.add(char)
        else:
            upper_present.add(char)

    # Count characters that have both their lowercase and uppercase versions present
    count = 0
    for char in lower_present:
        if char.upper() in upper_present:
            count += 1

    return count
