def last_non_empty_string(s: str) -> str:
    from collections import Counter

    freq = Counter(s)
    unique_count = sum(1 for c in freq if freq[c] > 0)

    # Simulate the rounds
    while True:
        chars_to_remove = set()
        for c in 'abcdefghijklmnopqrstuvwxyz':
            if c in freq and freq[c] > 0:
                chars_to_remove.add(c)

        if not chars_to_remove:
            break

        # Remove first occurrence of each char in chars_to_remove
        new_s = []
        seen = set()
        for ch in s:
            if ch in chars_to_remove and ch not in seen:
                seen.add(ch)
                freq[ch] -= 1
                if freq[ch] == 0:
                    del freq[ch]
                continue
            new_s.append(ch)

        # Check if this was the last operation
        remaining_chars = {c for c in freq if freq[c] > 0}
        if not remaining_chars:
            return s  # s is the string before this operation

        s = ''.join(new_s)

    return s
