import sys

def solve():
    # Read all lines, strip newlines, ignore empty lines (though input should be exactly 12)
    lines = [line.strip() for line in sys.stdin if line.strip() != '']
    if len(lines) < 12:
        # Not enough lines, but constraints guarantee 12
        print("No")
        return
    # Extract three polyominoes
    polyominoes = []
    for i in range(3):
        cells = []
        for r in range(4):
            row = lines[i*4 + r]
            for c, ch in enumerate(row):
                if ch == '#':
                    cells.append((r, c))
        polyominoes.append(cells)

    # Check total size
    sizes = [len(p) for p in polyominoes]
    if sum(sizes) != 16:
        print("No")
        return

    full_set = set(range(16))

    # Generate all placements for each polyomino
    def generate_placements(cells):
        placements = []
        # Four rotations: 0°, 90°, 180°, 270°
        for k in range(4):
            rotated = []
            for r, c in cells:
                if k == 0:
                    nr, nc = r, c
                elif k == 1:
                    nr, nc = c, -r
                elif k == 2:
                    nr, nc = -r, -c
                else:  # k == 3
                    nr, nc = -c, r
                rotated.append((nr, nc))
            # Normalize to min row/col = 0
            min_r = min(r for r, _ in rotated)
            min_c = min(c for _, c in rotated)
            normalized = [(r - min_r, c - min_c) for r, c in rotated]
            # Compute bounding box
            max_r = max(r for r, _ in normalized)
            max_c = max(c for _, c in normalized)
            h = max_r + 1
            w = max_c + 1
            # Try all translations inside the 4x4 grid
            for dr in range(0, 4 - h + 1):
                for dc in range(0, 4 - w + 1):
                    placement = frozenset((dr + r) * 4 + (dc + c) for r, c in normalized)
                    placements.append(placement)
        # Remove duplicates (e.g., symmetric shapes)
        return list(set(placements))

    placements = [generate_placements(poly) for poly in polyominoes]

    # Brute force search
    for p1 in placements[0]:
        for p2 in placements[1]:
            if p1.isdisjoint(p2):
                union12 = p1 | p2
                if len(union12) == sizes[0] + sizes[1]:
                    for p3 in placements[2]:
                        if p3.isdisjoint(union12) and (union12 | p3) == full_set:
                            print("Yes")
                            return
    print("No")

if __name__ == "__main__":
