import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    N = int(next(it))
    M = int(next(it))
    INF = 10**18

    # distance matrix: 0-indexed vertices
    dist = [[INF] * N for _ in range(N)]
    for i in range(N):
        dist[i][i] = 0

    for _ in range(M):
        u = int(next(it)) - 1
        v = int(next(it)) - 1
        w = int(next(it))
        # directed edge, may replace if multiple edges? but constraints say no duplicate edges.
        dist[u][v] = w

    # Floyd-Warshall
    for k in range(N):
        for i in range(N):
            for j in range(N):
                if dist[i][k] != INF and dist[k][j] != INF:
                    nd = dist[i][k] + dist[k][j]
                    if nd < dist[i][j]:
                        dist[i][j] = nd

    # DP over subsets: dp[mask][last] = min total weight to visit exactly the vertices in mask, ending at last
    full_mask = 1 << N
    dp = [[INF] * N for _ in range(full_mask)]

    # initialize: start at any vertex
    for i in range(N):
        dp[1 << i][i] = 0

    # iterate over all masks
    for mask in range(1, full_mask):
        # current ending vertex
        for last in range(N):
            if not (mask >> last) & 1:
                continue
            cur = dp[mask][last]
            if cur == INF:
                continue
            # try to go to next vertex
            for nxt in range(N):
                if (mask >> nxt) & 1:
                    continue
                if dist[last][nxt] == INF:
                    continue
                new_mask = mask | (1 << nxt)
                new_val = cur + dist[last][nxt]
                if new_val < dp[new_mask][nxt]:
                    dp[new_mask][nxt] = new_val

    # answer: min over all ending vertices
    full_mask = (1 << N) - 1
    ans = min(dp[full_mask][last] for last in range(N))

    if ans == INF:
        print("No")
    else:
        print(ans)

if __name__ == "__main__":
    solve()
