        elif d == diff_min_val:
            diff_min_indices.append(i)
        elif diff_second_min_val is None or d < diff_second_min_val:
            diff_second_min_val = d

    # Convert index lists to sets for O(1) lookup
    sum_max_set = set(sum_max_indices)
    sum_min_set = set(sum_min_indices)
    diff_max_set = set(diff_max_indices)
    diff_min_set = set(diff_min_indices)

    ans = float('inf')

    for i in range(n):
        # Compute new (x+y) max-min after removing i
        if i in sum_max_set:
            if len(sum_max_indices) > 1:
                cur_sum_max = sum_max_val
            else:
                # We need the next best max
                cur_sum_max = sum_second_max_val if sum_second_max_val is not None else sum_max_val
        else:
            cur_sum_max = sum_max_val

        if i in sum_min_set:
            if len(sum_min_indices) > 1:
                cur_sum_min = sum_min_val
            else:
                cur_sum_min = sum_second_min_val if sum_second_min_val is not None else sum_min_val
        else:
            cur_sum_min = sum_min_val

        sum_dist = cur_sum_max - cur_sum_min

        # Compute new (x-y) max-min after removing i
        if i in diff_max_set:
            if len(diff_max_indices) > 1:
                cur_diff_max = diff_max_val
            else:
                cur_diff_max = diff_second_max_val if diff_second_max_val is not None else diff_max_val
        else:
            cur_diff_max = diff_max_val

        if i in diff_min_set:
            if len(diff_min_indices) > 1:
                cur_diff_min = diff_min_val
            else:
                cur_diff_min = diff_second_min_val if diff_second_min_val is not None else diff_min_val
        else:
            cur_diff_min = diff_min_val

        diff_dist = cur_diff_max - cur_diff_min

        new_max = max(sum_dist, diff_dist)
        if new_max < ans:
            ans = new_max

    return ans
