    substring_map = {}
    for i, s in enumerate(arr):
        for sub in get_all_substrings(s):
            if sub not in substring_map:
                substring_map[sub] = set()
            substring_map[sub].add(i)

    answer = []
    for i, s in enumerate(arr):
