import sys

class BIT:
    def __init__(self, n):
        self.n = n
        self.bit = [0] * (n + 1)

    def add(self, idx, delta):
        while idx <= self.n:
            self.bit[idx] += delta
            idx += idx & -idx

    def sum(self, idx):
        res = 0
        while idx > 0:
            res += self.bit[idx]
            idx -= idx & -idx
        return res

    def range_sum(self, l, r):
        if l > r:
            return 0
        return self.sum(r) - self.sum(l - 1)

def solve() -> None:
    data = sys.stdin.buffer.read().split()
    it = iter(data)
    N = int(next(it))
    Q = int(next(it))
    S = next(it).decode()

    # Special case N == 1: no adjacent pairs
    if N == 1:
        out_lines = []
        for _ in range(Q):
            kind = int(next(it))
            L = int(next(it))
            R = int(next(it))
            if kind == 2:
                out_lines.append("Yes")
        sys.stdout.write("\n".join(out_lines))
        return

    # Build initial bad array (1-indexed, size N-1)
    bad = [0] * N  # we use indices 1..N-1, extra slot for convenience
    for i in range(1, N):
        if S[i-1] == S[i]:
            bad[i] = 1

    # Initialize BIT with bad values
    bit = BIT(N - 1)
    for i in range(1, N):
        if bad[i]:
            bit.add(i, 1)

    out = []
    for _ in range(Q):
        kind = int(next(it))
        L = int(next(it))
        R = int(next(it))
        if kind == 1:
            # Flip range [L, R]
            if L > 1:
                idx = L - 1
                # Toggle bad[idx]
                if bad[idx] == 0:
                    bit.add(idx, 1)
                    bad[idx] = 1
                else:
                    bit.add(idx, -1)
                    bad[idx] = 0
            if R < N:
                idx = R
                if bad[idx] == 0:
                    bit.add(idx, 1)
                    bad[idx] = 1
                else:
                    bit.add(idx, -1)
                    bad[idx] = 0
        else:  # kind == 2
            if L == R:
                out.append("Yes")
            else:
                total_bad = bit.range_sum(L, R - 1)
                out.append("Yes" if total_bad == 0 else "No")
    sys.stdout.write("\n".join(out))

