We need to solve the problem by finding the shortest path from the start to each special node, and between all special nodes, using BFS on a grid up to 300x300.  
Since at most 18 candies, we can use a bitmask DP for the Hamiltonian path-like problem.  

Here’s the plan:  
1. Parse input.  
2. Locate start, goal, and all candy positions.  
3. BFS from each special node (start, candies, goal) to compute distances to each other special node.  
4. If unreachable, output -1.  
5. Use DP[mask][i] = minimum steps to collect candies in mask and end at candy i.  
6. Try combinations with goal to maximize candy count within T.  

We'll implement the function below.  

```python
import sys
from collections import deque

def solve():
    input = sys.stdin.readline
    H, W, T = map(int, input().split())
    grid = [list(input().strip()) for _ in range(H)]

    start = goal = None
    candies = []
    for i in range(H):
        for j in range(W):
            if grid[i][j] == 'S':
                start = (i, j)
            elif grid[i][j] == 'G':
                goal = (i, j)
            elif grid[i][j] == 'o':
                candies.append((i, j))

    # Number of special nodes: start + candies + goal
    special = [start] + candies + [goal]
    n = len(special)
    k = len(candies)  # number of candies

    # Compute pairwise distances via BFS
    dist = [[-1]*n for _ in range(n)]
    directions = [(1,0),(-1,0),(0,1),(0,-1)]

    for idx, (si, sj) in enumerate(special):
        d = [[-1]*W for _ in range(H)]
        d[si][sj] = 0
        q = deque([(si, sj)])
        while q:
            i, j = q.popleft()
            for di, dj in directions:
                ni, nj = i+di, j+dj
                if 0 <= ni < H and 0 <= nj < W and grid[ni][nj] != '#' and d[ni][nj] == -1:
                    d[ni][nj] = d[i][j] + 1
                    q.append((ni, nj))
        for jdx, (ti, tj) in enumerate(special):
            dist[idx][jdx] = d[ti][tj]

    # If start to goal is unreachable or > T
    if dist[0][n-1] == -1 or dist[0][n-1] > T:
        print(-1)
        return

    # DP over subsets: dp[mask][i] = min steps ending at candy i (0-indexed among candies)
    INF = 10**9
    dp = [[INF]*k for _ in range(1<<k)]
    # start to each candy
    for i in range(k):
        if dist[0][i+1] != -1:
            dp[1<<i][i] = dist[0][i+1]

    # Fill DP
    for mask in range(1<<k):
        for last in range(k):
            if dp[mask][last] == INF:
                continue
            for nxt in range(k):
                if mask & (1<<nxt):
                    continue
                if dist[last+1][nxt+1] != -1:
                    nd = dp[mask][last] + dist[last+1][nxt+1]
                    if nd < dp[mask | (1<<nxt)][nxt]:
                        dp[mask | (1<<nxt)][nxt] = nd

    # Now compute best answer
    ans = 0
    for mask in range(1<<k):
        cnt = bin(mask).count('1')
        if cnt <= ans:
            continue
        # Try ending at goal from start or any candy in mask
        # From start directly
        if dist[0][n-1] <= T:
            ans = max(ans, 0)
        # From each candy in mask
        for last in range(k):
            if mask & (1<<last) and dp[mask][last] != INF:
                if dist[last+1][n-1] != -1 and dp[mask][last] + dist[last+1][n-1] <= T:
                    ans = max(ans, cnt)

    print(ans)

if __name__ == "__main__":
    solve()
```

