def min_equal_sum(nums1, nums2):
    sum1, zero1 = sum(nums1), nums1.count(0)
    sum2, zero2 = sum(nums2), nums2.count(0)

    if sum1 == sum2 and zero1 == 0 and zero2 == 0:
        return sum1

    if zero1 == 0 and zero2 == 0:
        return -1 if sum1 != sum2 else sum1

    # Minimum possible sum for each array if all zeros become 1
    min_sum1 = sum1 + zero1
    min_sum2 = sum2 + zero2

    if min_sum1 > min_sum2:
        # Try to match by increasing nums2's zeros
        diff = min_sum1 - min_sum2
        if zero2 == 0:
            return -1
        # Each zero in nums2 can increase its sum by at most (10^6 - 1),
        # but we only need +diff, which is possible if diff <= max possible increase
        # We only need to know if it's possible; we don't need to minimize further
        if diff <= (10**6 - 1) * zero2:
            return min_sum1
        else:
            return -1
    elif min_sum2 > min_sum1:
        diff = min_sum2 - min_sum1
        if zero1 == 0:
            return -1
        if diff <= (10**6 - 1) * zero1:
            return min_sum2
        else:
            return -1
    else:  # min sums equal
        return min_sum1
