def minimumCost(source, target, original, changed, cost):
    # Use Floyd-Warshall to find the shortest path between all character pairs
    # Initialize a 26x26 matrix with infinity
    dist = [[float('inf')] * 26 for _ in range(26)]

    # Distance to self is 0
    for i in range(26):
        dist[i][i] = 0

    # Populate initial costs
    for u, v, c in zip(original, changed, cost):
        u_idx = ord(u) - ord('a')
        v_idx = ord(v) - ord('a')
        dist[u_idx][v_idx] = min(dist[u_idx][v_idx], c)

    # Floyd-Warshall algorithm to find all-pairs shortest paths
    for k in range(26):
        for i in range(26):
            if dist[i][k] != float('inf'):
                for j in range(26):
                    if dist[k][j] != float('inf'):
                        dist[i][j] = min(dist[i][j], dist[i][k] + dist[k][j])

    total_cost = 0
    for s_char, t_char in zip(source, target):
        if s_char == t_char:
            continue

        s_idx = ord(s_char) - ord('a')
        t_idx = ord(t_char) - ord('a')

        if dist[s_idx][t_idx] == float('inf'):
            return -1

        total_cost += dist[s_idx][t_idx]

    return total_cost
