import sys
from collections import deque

def solve() -> None:
    data = sys.stdin.buffer.read().split()
    it = iter(data)
    N = int(next(it))

    # prerequisite lists: for each book i, list of books that must be read before i
    prereqs = [[] for _ in range(N + 1)]
    for i in range(1, N + 1):
        c = int(next(it))
        for _ in range(c):
            p = int(next(it))
            prereqs[i].append(p)

    # 1. Find all books that must be read before (or including) book 1
    visited = [False] * (N + 1)
    q = deque()
    q.append(1)
    visited[1] = True
    while q:
        node = q.popleft()
        for p in prereqs[node]:
            if not visited[p]:
                visited[p] = True
                q.append(p)

    # 2. Build reverse dependency graph (prerequisite -> dependent) for required books (excluding book 1)
    dependents = [[] for _ in range(N + 1)]
    for i in range(1, N + 1):
        if visited[i] and i != 1:
            for p in prereqs[i]:
                # p is also visited because it is a prerequisite of a required book
                dependents[p].append(i)

    # 3. Compute indegree in the reverse graph (number of prerequisites)
    indeg = [0] * (N + 1)
    for i in range(1, N + 1):
        if visited[i] and i != 1:
            indeg[i] = len(prereqs[i])

    # 4. Kahn's topological sort
    q = deque()
    for i in range(1, N + 1):
        if visited[i] and i != 1 and indeg[i] == 0:
            q.append(i)

    order = []
    while q:
        node = q.popleft()
        order.append(node)
        for dep in dependents[node]:
            indeg[dep] -= 1
            if indeg[dep] == 0:
                q.append(dep)

    # 5. Output the reading order
    print(' '.join(map(str, order)))

