```python
def minimumBeautifulPartitions(s: str) -> int:
    # Precompute powers of 5 in binary format
    # Since len(s) <= 15, 5^x <= 2^15 - 1 = 32767
    # 5^0 = 1, 5^1 = 5, 5^2 = 25, 5^3 = 125, 5^4 = 625, 5^5 = 3125, 5^6 = 15625
    powers_of_5 = {bin(5**i)[2:] for i in range(7)}

    n = len(s)
    # dp[i] will store the minimum number of substrings for s[i:]
    # Initialize with infinity
    memo = {}

    def solve(start):
        if start == n:
            return 0
        if start in memo:
            return memo[start]

        # If the substring starts with '0', it's invalid (no leading zeros)
        if s[start] == '0':
            return float('inf')

        res = float('inf')
        # Try all possible end positions for the current substring
        for end in range(start + 1, n + 1):
            sub = s[start:end]
            if sub in powers_of_5:
                count = solve(end)
                if count != float('inf'):
                    res = min(res, 1 + count)

        memo[start] = res
        return res

    result = solve(0)
    return result if result != float('inf') else -1
