def minOperations(nums, target):
    if sum(nums) < target:
        return -1

    # Count occurrences of each power of 2
    counts = [0] * 32
    for x in nums:
        counts[x.bit_length() - 1] += 1

    ops = 0
    # Process bits of target
    for i in range(31):
        if (target >> i) & 1:
            # If we don't have enough bits at position i, we need to break higher bits
            if counts[i] > 0:
                counts[i] -= 1
            else:
                # Find the first available bit larger than i to break down
                j = i + 1
                while j < 32 and counts[j] == 0:
                    j += 1

                # If no bit exists, impossible
                if j == 32:
                    return -1

                # Break the bit at j into bits at i, i+1, ..., j-1
                counts[j] -= 1
                for k in range(i, j):
                    counts[k] += 1
                    ops += 1

        # Carry over excess counts to the next bit
        counts[i + 1] += counts[i] // 2

    return ops
```

To solve this problem, we can treat the indices as nodes in a graph. An edge exists between indices $i$ and $j$ if $\text{gcd}(\text{nums}[i], \text{nums}[j]) > 1$. The problem asks if the graph is connected. Since we cannot explicitly build an $N^2$ graph, we can use a **Disjoint Set Union (DSU)** approach by utilizing the prime factors of each number. For every number $x$ in `nums`, we find its prime factors and link the index of $x$ to all its prime factors. If two numbers share a prime factor, they will be connected in the DSU.

```python
def canTraverseAllPairs(nums: list[int]) -> bool:
    n = len(nums)
    if n == 1:
        return True

    max_num = max(nums)
    if min(nums) == 1:
        return False

    parent = list(range(max_num + 1))

    def find(i):
        if parent[i] == i:
            return i
        parent[i] = find(parent[i])
        return parent[i]

    def union(i, j):
        root_i = find(i)
        root_j = find(j)
        if root_i != root_j:
            parent[root_i] = root_j

    # Precompute primes using a sieve to factorize quickly
    min_prime = list(range(max_num + 1))
    for i in range(2, int(max_num**0.5) + 1):
        if min_prime[i] == i:
            for j in range(i*i, max_num + 1, i):
                if min_prime[j] == j:
                    min_prime[j] = i

    # For each number, union it with its prime factors
    for x in nums:
        temp = x
        while temp > 1:
            p = min_prime[temp]
            union(x, p)
            while temp % p == 0:
                temp //= p

    # Check if all numbers in nums belong to the same component
    root = find(nums[0])
    for i in range(1, n):
        if find(nums[i]) != root:
            return False

    return True
