To solve this problem, we can use dynamic programming with bitmasking. Since the length of `nums` is at most 14, we can represent the set of visited numbers using a bitmask of size $2^n$. The state will be `dp(mask, last_idx)`, which represents the number of special permutations using the elements indicated by `mask`, ending with the element at `last_idx`.

```python
def specialPerm(nums):
    n = len(nums)
    MOD = 10**9 + 7

    # Precompute adjacency matrix to speed up divisibility checks
    adj = [[False] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            if i != j:
                if nums[i] % nums[j] == 0 or nums[j] % nums[i] == 0:
                    adj[i][j] = True

    # memo[mask][last_idx] stores the count of special permutations
    memo = [[-1] * n for _ in range(1 << n)]

    def solve(mask, last_idx):
        # Base case: all numbers have been used
        if mask == (1 << n) - 1:
            return 1

        if memo[mask][last_idx] != -1:
            return memo[mask][last_idx]

        res = 0
        for next_idx in range(n):
            # If next_idx is not in mask and satisfies the special condition
            if not (mask & (1 << next_idx)) and adj[last_idx][next_idx]:
                res = (res + solve(mask | (1 << next_idx), next_idx)) % MOD

        memo[mask][last_idx] = res
        return res

    total = 0
    # Try starting the permutation with each element
    for i in range(n):
        total = (total + solve(1 << i, i)) % MOD

    return total
