def min_operations(s1: str, s2: str, s3: str) -> int:
    # Find the length of the longest common prefix
    min_len = min(len(s1), len(s2), len(s3))
    lcp = 0
    for i in range(min_len):
        if s1[i] == s2[i] == s3[i]:
            lcp += 1
        else:
            break
    # If no common prefix exists, it's impossible
    if lcp == 0:
        return -1
    # Total deletions = sum of lengths - 3 * common prefix length
    return len(s1) + len(s2) + len(s3) - 3 * lcp
